Object.assign(words,{"receiveCurrency":["받는 금액 · 예상","You receive · Estimate","受取金額・目安","预计收到金额","預估收到金額"],"fromCurrency":["보내는 통화","From currency","両替元の通貨","支付币种","付款幣別"],"toCurrency":["받는 통화","To currency","受取通貨","接收币种","收款幣別"],"swap":["보내는 통화와 받는 통화 바꾸기","Swap currencies and amounts","通貨と金額を入れ替える","交换币种和金额","交換幣別與金額"],"customRate":["예시 환율 직접 입력","Enter a demo rate","デモレートを入力","手动输入示例汇率","手動輸入範例匯率"],"rateHelp":["예시값이 없는 통화는 1단위당 KRW 값을 입력하세요. 실시간 환율이 아닙니다.","For unlisted rates, enter the KRW value of one unit. Not a live rate.","デモ値がない通貨は1単位のKRW値を入力。実勢レートではありません。","没有示例值的币种，请输入每单位对应的KRW值。非实时汇率。","沒有範例值的幣別，請輸入每單位對應的KRW值。非即時匯率。"],"rateMissing":["예시 환율을 입력해주세요.","Enter a demo exchange rate.","デモレートを入力してください。","请输入示例汇率。","請輸入範例匯率。"],"rateBase":["1단위의 KRW 값","KRW per unit","1単位のKRW値","每单位KRW值","每單位KRW值"],"startRoute":["길안내 시작","Start directions","ルート案内を開始","开始导航","開始導航"],"endRoute":["길안내 종료","End directions","案内を終了","结束导航","結束導航"],"navigating":["ATM으로 이동 중","On your way to the ATM","ATMへ移動中","正在前往ATM","正在前往ATM"],"instructions":["ATM 이용 안내","ATM instructions","ATM操作案内","ATM操作说明","ATM操作說明"],"nearest":["가까운 제휴 ATM","Nearby partner ATM","近くの提携ATM","附近合作ATM","附近合作ATM"],"browseMap":["주변 ATM 둘러보기","Explore nearby ATMs","周辺ATMを見る","浏览附近ATM","瀏覽附近ATM"],"recenter":["예시 위치로 이동","Center demo location","デモ位置を中央に","回到示例位置","回到範例位置"],"zoomIn":["지도 확대","Zoom in","地図を拡大","放大地图","放大地圖"],"zoomOut":["지도 축소","Zoom out","地図を縮小","缩小地图","縮小地圖"],"linked":["환전 신청과 연결됨","Linked to your request","両替申込と連携中","已关联换汇申请","已連結換匯申請"],"demoSupport":["통화 조합을 체험하는 화면입니다. 실제 은행·ATM 지원 통화는 별도 확인이 필요합니다.","Currency-pair demo. Actual bank and ATM currency support must be confirmed.","通貨ペアのデモです。銀行・ATMの対応通貨は別途確認が必要です。","币种组合演示，实际银行与ATM支持币种需另行确认。","幣別組合展示，實際銀行與ATM支援幣別需另行確認。"]});
words.applyDesc=['보내는 통화와 받는 통화를 자유롭게 선택하세요.','Choose the currencies you give and receive.','両替元と受取の通貨を選んでください。','自由选择支付与接收币种。','自由選擇付款與收款幣別。'];
const rates={KRW:1,USD:1400,JPY:9.3,CNY:195,TWD:43,EUR:1510,GBP:1800,HKD:180,SGD:1040,AUD:920,CAD:1020,CHF:1590,THB:40,VND:0.055,MYR:315,IDR:0.089,PHP:24,INR:16.5,NZD:840};
const currencyCodes=[...new Set(['KRW','USD','JPY','CNY','TWD','EUR','GBP',...(typeof Intl.supportedValuesOf==='function'?Intl.supportedValuesOf('currency'):Object.keys(rates))])];
const customRates={};
function rateFor(c){return rates[c]??customRates[c];}
function ratePair(){const a=rateFor(state.draft.currency),b=rateFor(state.draft.toCurrency);return state.draft.currency===state.draft.toCurrency?1:(a>0&&b>0?a/b:null);}
function currencyOptions(selected){return currencyCodes.map(c=>'<option value="'+c+'" '+(c===selected?'selected':'')+'>'+c+'</option>').join('');}
function currencyName(c){try{return new Intl.DisplayNames([language],{type:'currency'}).of(c);}catch{return c;}}
function formatMoney(n,c){try{return new Intl.NumberFormat(language,{style:'currency',currency:c,currencyDisplay:'code'}).format(n).replace(c,'').trim();}catch{return Number(n).toFixed(2);}}
function exchangeIcon(){return '<svg viewBox="0 0 32 24" aria-hidden="true" class="exchange-symbol"><path d="M28 9A12.7 9 0 0 0 5 6.5"/><path d="m5 2.7-.5 4.6 4.6-1.1M4 15a12.7 9 0 0 0 23 2.5"/><path d="m27 21.3.5-4.6-4.6 1.1"/><path d="M18.4 9.1c-.7-1-4.8-1.4-4.8.8 0 2.1 4.8 1.4 4.8 3.7 0 2.2-4.1 2.1-5 .8M16 7.2v9.6" class="small-money"/></svg>';}

let language='ko';try{const saved=localStorage.getItem('qr-exchange-language');if(locales.includes(saved))language=saved;}catch{}
const state={draft:{currency:'USD',toCurrency:'KRW',amount:'100',area:'haeundae',name:''},request:null,selected:0,navigating:false,mapZoom:1,mapArea:null,loadingTarget:'apply',loadingTimers:[],paperStop:null,codeInterval:null,toastTimer:null};
const screen=document.querySelector('#screen');const drawer=document.querySelector('#more-drawer');const routeDialog=document.querySelector('#route-dialog');
const t=k=>words[k]?.[locales.indexOf(language)]??k;const region=key=>regions[key]?.[locales.indexOf(language)]??key;const icon=name=>name==='cash'?exchangeIcon():`<svg aria-hidden="true"><use href="#i-${name}"/></svg>`;
const esc=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const number=value=>Number(value).toLocaleString(language,{maximumFractionDigits:0});
function route(){return location.hash.replace('#/','')||'exchange';}
function go(page){if(route()===page)render();else location.hash='/'+page;}
function progress(step,title,back='exchange'){return `<div class="step-head"><button class="back-button" data-go="${back}" aria-label="${t('back')}">${icon('back')}</button><span class="step-title">${title}</span><span class="step-count">0${step} / 04</span></div><div class="progress" aria-label="${step} / 4">${[1,2,3,4].map(n=>`<span class="${n<step?'active':n===step?'current':''}"></span>`).join('')}</div>`;}
function home(){return `<div class="home-heading"><span class="eyebrow">YOUR NEXT MOMENT, BUSAN.</span><h1>${t('homeTitle')}</h1><p>${t('homeDesc')}</p></div><section class="exchange-hero"><div class="hero-card-head"><span>${t('heroLabel')}</span><span class="status-dot"></span></div><div class="cash-art" aria-hidden="true"><div class="note"></div><div class="note"></div><div class="note"><span class="won">₩</span></div><span class="spark">✦</span><span class="spark small">✧</span></div><p class="hero-card-copy">${t('heroCopy')}</p><button class="button gold" id="start-exchange">${t('start')}${icon('chevron')}</button></section><div class="section-label"><h2>${t('journey')}</h2><span>01 — 03</span></div><div class="journey-list">${[['cash','step1','step1Desc'],['qr','step2','step2Desc'],['pin','step3','step3Desc']].map(([i,a,b],n)=>`<div class="journey-item"><span class="journey-icon">${icon(i)}</span><div><h3>${t(a)}</h3><p>${t(b)}</p></div><span class="number">0${n+1}</span></div>`).join('')}</div><p class="home-note">${icon('shield')}<span>${t('homeNote')}</span></p>`;}
function apply(){const d=state.draft;return `${progress(1,t('apply'))}<div class="page-intro"><span class="eyebrow">YOUR MONEY, YOUR WAY.</span><h1>${t('applyTitle')}</h1><p>${t('applyDesc')}</p></div><form id="apply-form"><div class="currency-pair"><div class="form-card source-card"><label class="field-label" for="give-amount">${t('give')}<span>${t('demo')}</span></label><div class="field-controls"><div class="currency-choice"><select id="currency" class="currency-select" aria-label="${t('fromCurrency')}">${currencyOptions(d.currency)}</select><small id="source-name">${currencyName(d.currency)}</small></div><input id="give-amount" class="amount-input" type="number" inputmode="decimal" min="0.00000001" max="1000000000000" step="any" required value="${esc(d.amount)}" aria-label="${t('give')}"></div></div><button type="button" id="swap-currencies" class="swap-button" aria-label="${t('swap')}">${exchangeIcon()}</button><div class="form-card receive-card"><label class="field-label" for="receive-currency">${t('receiveCurrency')}</label><div class="field-controls"><div class="currency-choice"><select id="receive-currency" class="currency-select" aria-label="${t('toCurrency')}">${currencyOptions(d.toCurrency)}</select><small id="target-name">${currencyName(d.toCurrency)}</small></div><output class="estimate-amount" id="estimate" aria-live="polite"></output></div><div class="estimate-bottom"><span>${t('sampleRate')}</span><span id="rate-text" class="rate-text"></span></div></div></div><div id="custom-rates" class="custom-rates" hidden></div><p class="form-error" id="amount-error" hidden></p><div class="form-card"><label for="pickup-area" class="field-label">${t('area')}</label><select id="pickup-area" class="form-select">${Object.keys(regions).map(key=>'<option value="'+key+'" '+(key===d.area?'selected':'')+'>'+region(key)+'</option>').join('')}</select></div><div class="form-card"><label class="field-label" for="demo-name">${t('name')}<span>${t('optional')}</span></label><input id="demo-name" class="name-input" maxlength="60" autocomplete="off" placeholder="${t('namePlaceholder')}" value="${esc(d.name)}"><p class="name-hint">${t('nameHint')}</p></div><p class="form-explainer">${t('applyNote')}<br><br>${t('quoteNote')}<br>${t('demoSupport')}</p><div class="form-actions"><button class="button gold" type="submit">${t('submit')}${icon('chevron')}</button></div><details class="live-rates"><summary><span class="live-rates-icon">${icon('clock')}</span><span class="live-rates-title">${t('liveRates')}</span><span class="live-soon">${t('liveSoon')}</span><span class="live-expand">${icon('chevron')}</span></summary><div class="live-rates-content"><p>${t('liveDesc')}</p><table><thead><tr><th>${t('ratePairLabel')}</th><th>${t('rateValueLabel')}</th></tr></thead><tbody>${['USD / KRW','JPY / KRW','CNY / KRW','TWD / KRW','EUR / KRW'].map(pair=>'<tr><td>'+pair+'</td><td>—</td></tr>').join('')}</tbody></table><div class="live-update"><span>${t('rateUpdated')}</span><span>—</span></div><span class="live-offline"><i></i>${t('liveOffline')}</span></div></details></form>`;}
function loading(){return `<section class="loading-screen" aria-busy="true"><span class="eyebrow">PREPARING YOUR NEXT MOMENT</span><div class="paper-stage"><canvas id="paper-loader" aria-hidden="true"></canvas></div><h1>${t('loadingTitle')}</h1><p>${t('loadingDesc')}</p><div class="loading-track paper-track" aria-hidden="true"><span id="paper-progress"></span></div><div class="loading-status" id="loading-status" role="status">${t(state.loadingTarget==='apply'?'loading1':'loading2')}</div><span class="loading-small">${t('loadingDemo')}</span></section>`;}
function missing(){return `<div class="page-intro"><h1>${t('missing')}</h1><p>${t('homeNote')}</p></div><button class="button gold" data-go="apply">${t('start')}</button>`;}
function code(){const r=state.request;if(!r)return missing();return `${progress(2,t('codeStep'),'apply')}<div class="page-intro"><h1>${t('codeTitle')}</h1><p>${t('codeDesc')}</p></div><div class="code-card"><div class="code-top"><span class="approved">${icon('check')}${t('issued')}</span><span class="demo-tag">DEMO</span></div><h2>${t('withdrawalCode')}</h2><div class="withdrawal-code" id="withdrawal-code">${r.code.slice(0,3)} ${r.code.slice(3)}</div><button id="copy-code" class="copy-code">${icon('copy')}${t('copy')}</button><div class="ticket-bottom"><span>${icon('clock')}${t('remaining')}</span><strong id="code-time">10:00</strong></div></div><div class="summary-card"><span class="summary-label">${t('receive')}</span><div class="summary-amount">${r.toCurrency||'KRW'} ${formatMoney(r.received??r.won,r.toCurrency||'KRW')}</div><p>${t('from')} ${r.currency} ${number(r.amount)} · ${region(r.area)}</p></div><div class="next-card">${icon('pin')}<div><h3>${t('next')}</h3><p>${t('nextDesc')}</p></div></div><div class="code-actions"><button class="button gold" data-go="map">${t('findAtm')}${icon('chevron')}</button><button class="button quiet" id="reissue">${t('reissue')}</button></div><p class="code-note">${t('codeDemo')}</p>`;}
function placeName(){const area=state.mapArea||state.request?.area||state.draft.area;return region(area)+' '+t('partnerAtm')+' '+String(state.selected+1).padStart(2,'0');}
function mapPage(){const area=state.mapArea||state.request?.area||state.draft.area;return `<section class="map-experience"><div class="map-canvas" role="group" aria-label="${t('demoMap')}"><div class="map-geometry" style="--zoom:${state.mapZoom}"><div class="map-water"></div><div class="map-road r1"></div><div class="map-road r2"></div><div class="map-road r3"></div><div class="map-park park-one"></div><div class="map-park park-two"></div><span class="map-landmark landmark-one">${region(area)}</span><span class="map-landmark landmark-two">BUSAN</span><span class="sea-label">SEA</span>${state.navigating?'<svg class="map-route-line" viewBox="0 0 440 800" preserveAspectRatio="none"><path d="'+['M141 440 L141 320 Q141 296 185 296 L237 276','M141 440 L115 440 Q84 440 84 410 L84 364','M141 440 L141 270 Q141 245 210 245 L339 172'][state.selected]+'"/></svg>':''}<span class="map-user-dot" aria-label="Demo location"></span>${[0,1,2].map(i=>'<button class="map-pin p'+(i+1)+' '+(state.selected===i?'active':'')+'" data-place="'+i+'" aria-label="'+t('partnerAtm')+' '+(i+1)+'" aria-pressed="'+(state.selected===i)+'"><span>'+(i+1)+'</span></button>').join('')}</div></div><div class="map-toolbar"><span class="map-search-icon">${icon('pin')}</span><select id="map-area" aria-label="${t('area')}">${Object.keys(regions).map(key=>'<option value="'+key+'" '+(area===key?'selected':'')+'>'+region(key)+' · '+t('partnerAtm')+'</option>').join('')}</select><span class="demo-pill">DEMO</span></div>${state.request?'<button class="map-code-chip" data-go="code">'+icon('qr')+'<span>'+'03 / 04 · '+t('linked')+'<strong>'+state.request.code.slice(0,3)+' '+state.request.code.slice(3)+'</strong></span>'+icon('chevron')+'</button>':'<span class="map-browse-chip">'+t('browseMap')+'</span>'}<div class="map-controls"><button id="map-recenter" aria-label="${t('recenter')}">${icon('pin')}</button><div><button id="map-zoom-in" aria-label="${t('zoomIn')}">+</button><button id="map-zoom-out" aria-label="${t('zoomOut')}">−</button></div></div><div class="map-attribution">${t('demoMap')} · API NOT CONNECTED</div><section class="map-dock"><div class="dock-handle"></div><div class="map-dock-eyebrow">${state.navigating?t('navigating'):t('nearest')}<span>${t('walk')} ${[5,8,12][state.selected]} ${t('minute')}</span></div><div class="place-title-row"><span class="atm-icon">${icon('atm')}</span><div><h1>${placeName()}</h1><p>09:00–22:00 · ${t('demoMap')}</p></div><button id="atm-instructions" class="icon-button" aria-label="${t('instructions')}">${icon('more')}</button></div><div class="map-place-tabs">${[0,1,2].map(i=>'<button class="'+(state.selected===i?'active':'')+'" data-place="'+i+'" aria-pressed="'+(state.selected===i)+'">ATM 0'+(i+1)+'</button>').join('')}</div>${state.navigating&&state.request?'<button id="collected" class="button gold">'+t('collected')+icon('check')+'</button>':'<button id="directions" class="button gold">'+icon('pin')+t('startRoute')+'</button>'}${state.navigating?'<button id="end-directions" class="end-directions">'+t('endRoute')+'</button>':''}</section></section>`;}
function done(){return `${progress(4,t('doneStep'))}<div class="done-intro"><div class="success-art">${icon('check')}</div><span class="eyebrow">ENJOY YOUR NEXT MOMENT.</span><h1>${t('doneTitle')}</h1><p>${t('doneDesc')}</p><span class="demo-tag">${t('demo')}</span></div><div class="privacy-card">${icon('shield')}<div><h3>${t('clearedTitle')}</h3><p>${t('clearedDesc')}</p></div></div><div class="next-card">${icon('cash')}<div><h3>${t('again')}</h3><p>${t('step3Desc')}</p></div></div><p class="home-note">${t('doneDemo')}</p><div class="done-actions"><button class="button gold" data-go="apply">${t('again')}${icon('chevron')}</button><button class="button quiet" data-go="map">${t('findAtm')}</button></div>`;}
function updateStatic(){document.documentElement.lang=language;document.querySelectorAll('[data-t]').forEach(el=>el.innerHTML=t(el.dataset.t));document.querySelector('.language-toggle').setAttribute('aria-label',t('language'));document.querySelectorAll('.close-drawer,.close-route').forEach(el=>el.setAttribute('aria-label',t('close')));document.querySelector('.brand').setAttribute('aria-label','QR '+t('exchange'));document.querySelectorAll('[data-lang]').forEach(b=>b.setAttribute('aria-selected',String(b.dataset.lang===language)));document.title=`QR ${t('exchange')} · Busan`;}
function clearTimers(){state.paperStop?.();state.paperStop=null;state.loadingTimers.forEach(clearTimeout);state.loadingTimers=[];clearInterval(state.codeInterval);state.codeInterval=null;}
function render(options={}){clearTimers();updateStatic();const page=route();const screens={exchange:home,apply,loading,code,map:mapPage,done};screen.innerHTML=(screens[page]||home)();document.querySelector('.phone-app').classList.toggle('map-mode',page==='map');if(page==='map')wireMap();document.querySelectorAll('[data-tab]').forEach(a=>{const active=(page==='map'?'map':'exchange')===a.dataset.tab;a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});document.querySelectorAll('[data-go]').forEach(b=>b.addEventListener('click',()=>go(b.dataset.go)));screen.querySelector('#start-exchange')?.addEventListener('click',()=>beginLoading('apply'));screen.querySelector('#reissue')?.addEventListener('click',()=>beginLoading('code'));screen.querySelector('#copy-code')?.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(state.request.code);toast(t('copied'));}catch{toast(t('copyFail'));}});screen.querySelectorAll('[data-place]').forEach(b=>b.addEventListener('click',()=>{const scroll=window.scrollY;state.selected=Number(b.dataset.place);state.navigating=false;render({preserveScroll:true});window.scrollTo(0,scroll);}));screen.querySelector('#directions')?.addEventListener('click',()=>{state.navigating=true;render({preserveScroll:true});});screen.querySelector('#collected')?.addEventListener('click',()=>{state.request=null;state.draft={currency:'USD',toCurrency:'KRW',amount:'100',area:'haeundae',name:''};go('done');});if(page==='apply')wireForm();if(page==='loading')startLoading();if(page==='code'&&state.request){updateCountdown();state.codeInterval=setInterval(updateCountdown,1000);}if(!options.preserveScroll){window.scrollTo({top:0,behavior:'instant'});screen.focus({preventScroll:true});}}
function wireForm(){const form=document.querySelector('#apply-form');form.addEventListener('input',e=>{readDraft();if(e.target.matches('[data-custom-rate]'))customRates[e.target.dataset.customRate]=Number(e.target.value);updateEstimate();});form.addEventListener('change',e=>{readDraft();if(e.target.matches('#currency,#receive-currency'))renderRateInputs();updateEstimate();});document.querySelector('#swap-currencies').addEventListener('click',()=>{readDraft();const d=state.draft;const pair=ratePair();const next=pair?Number(d.amount)*pair:null;[d.currency,d.toCurrency]=[d.toCurrency,d.currency];if(next!==null&&Number.isFinite(next)&&next>0)d.amount=String(Number(next.toPrecision(12)));const y=scrollY;render({preserveScroll:true});window.scrollTo(0,y);document.querySelector('#swap-currencies').classList.add('just-swapped');});form.addEventListener('submit',e=>{e.preventDefault();readDraft();const n=Number(state.draft.amount),pair=ratePair();if(!Number.isFinite(n)||n<=0||n>1e12||!pair){const error=document.querySelector('#amount-error');error.textContent=!pair?t('rateMissing'):t('amountError');error.hidden=false;return;}state.request={currency:state.draft.currency,toCurrency:state.draft.toCurrency,amount:n,area:state.draft.area,received:Number((n*pair).toFixed(2)),won:Math.round(n*pair),code:'482917',expires:0};state.selected=0;state.mapArea=state.request.area;state.navigating=false;state.mapZoom=1;beginLoading('code');});renderRateInputs();updateEstimate();}
function renderRateInputs(){const area=document.querySelector('#custom-rates');const missing=state.draft.currency===state.draft.toCurrency?[]:[...new Set([state.draft.currency,state.draft.toCurrency])].filter(c=>!(c in rates));area.hidden=missing.length===0;area.innerHTML=missing.length?'<h3>'+t('customRate')+'</h3><p>'+t('rateHelp')+'</p>'+missing.map(c=>'<label>'+c+' · '+t('rateBase')+'<input type="number" inputmode="decimal" min="0.000001" step="any" data-custom-rate="'+c+'" value="'+(customRates[c]||'')+'" placeholder="1 '+c+' = ? KRW"></label>').join(''):'';}
function readDraft(){if(!document.querySelector('#apply-form'))return;state.draft.currency=document.querySelector('#currency').value;state.draft.toCurrency=document.querySelector('#receive-currency').value;state.draft.amount=document.querySelector('#give-amount').value;state.draft.area=document.querySelector('#pickup-area').value;state.draft.name=document.querySelector('#demo-name').value;}
function updateEstimate(){const d=state.draft,a=Number(d.amount),pair=ratePair(),valid=d.amount!==''&&Number.isFinite(a)&&a>0&&a<=1e12;document.querySelector('#estimate').textContent=valid&&pair?formatMoney(a*pair,d.toCurrency):'—';document.querySelector('#rate-text').textContent=pair?'1 '+d.currency+' = '+Number(pair.toPrecision(6)).toLocaleString(language,{maximumFractionDigits:6})+' '+d.toCurrency:t('rateMissing');document.querySelector('#source-name').textContent=currencyName(d.currency);document.querySelector('#target-name').textContent=currencyName(d.toCurrency);document.querySelector('#amount-error').hidden=true;}
function beginLoading(target){state.loadingTarget=target;go('loading');}
function startLoading(){const target=state.loadingTarget;const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;const duration=reduced?450:target==='apply'?1400:1900;state.paperStop=window.startPaperLoader(document.querySelector('#paper-loader'),{duration,reducedMotion:reduced});document.querySelector('#paper-progress').style.setProperty('--count-duration',duration+'ms');if(target==='code')state.loadingTimers.push(setTimeout(()=>{const label=document.querySelector('#loading-status');if(label)label.textContent=t('loading3');},Math.floor(duration*.5)));state.loadingTimers.push(setTimeout(()=>{if(target==='code'&&state.request){state.request.expires=Date.now()+600000;}go(target==='code'&&!state.request?'apply':target);},duration));}
function updateCountdown(){const el=document.querySelector('#code-time');if(!el||!state.request)return;const left=Math.max(0,Math.ceil((state.request.expires-Date.now())/1000));el.textContent=left?`${String(Math.floor(left/60)).padStart(2,'0')}:${String(left%60).padStart(2,'0')}`:t('expired');}

function wireMap(){document.querySelector('#map-area').addEventListener('change',e=>{state.mapArea=e.target.value;state.selected=0;state.navigating=false;render({preserveScroll:true});});document.querySelector('#map-zoom-in').addEventListener('click',()=>{state.mapZoom=Math.min(1.8,state.mapZoom+.2);render({preserveScroll:true});});document.querySelector('#map-zoom-out').addEventListener('click',()=>{state.mapZoom=Math.max(.8,state.mapZoom-.2);render({preserveScroll:true});});document.querySelector('#map-recenter').addEventListener('click',()=>{state.mapZoom=1;render({preserveScroll:true});toast(t('recenter'));});document.querySelector('#end-directions')?.addEventListener('click',()=>{state.navigating=false;render({preserveScroll:true});});document.querySelector('#atm-instructions').addEventListener('click',()=>{document.querySelector('#route-place').textContent=placeName();routeDialog.showModal();});}
function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.classList.add('visible');clearTimeout(state.toastTimer);state.toastTimer=setTimeout(()=>el.classList.remove('visible'),2800);}
const langToggle=document.querySelector('.language-toggle'),langMenu=document.querySelector('.language-menu');
function closeLanguages(focus=false){langMenu.hidden=true;langToggle.setAttribute('aria-expanded','false');if(focus)langToggle.focus();}
function openLanguages(focus=false){langMenu.hidden=false;langToggle.setAttribute('aria-expanded','true');if(focus)langMenu.querySelector('[aria-selected="true"]').focus();}
langToggle.addEventListener('click',()=>langMenu.hidden?openLanguages():closeLanguages());langToggle.addEventListener('keydown',e=>{if(e.key==='ArrowDown'){e.preventDefault();openLanguages(true);}});
langMenu.querySelectorAll('[data-lang]').forEach(b=>b.addEventListener('click',()=>{readDraft();language=b.dataset.lang;try{localStorage.setItem('qr-exchange-language',language);}catch{}render({preserveScroll:true});closeLanguages(true);}));
langMenu.addEventListener('keydown',e=>{const buttons=[...langMenu.querySelectorAll('[data-lang]')];const i=buttons.indexOf(document.activeElement);if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();buttons[(i+(e.key==='ArrowDown'?1:-1)+buttons.length)%buttons.length].focus();}if(e.key==='Escape'){e.preventDefault();closeLanguages(true);}});
document.addEventListener('click',e=>{if(!e.target.closest('.language'))closeLanguages();});document.addEventListener('focusin',e=>{if(!e.target.closest('.language'))closeLanguages();});document.addEventListener('keydown',e=>{if(e.key==='Escape')closeLanguages();});
const moreButton=document.querySelector('#more-button');moreButton.addEventListener('click',()=>{closeLanguages();drawer.showModal();moreButton.setAttribute('aria-expanded','true');});document.querySelector('.close-drawer').addEventListener('click',()=>drawer.close());drawer.addEventListener('close',()=>{moreButton.setAttribute('aria-expanded','false');moreButton.focus();});drawer.addEventListener('click',e=>{if(e.target===drawer){const r=drawer.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right)drawer.close();}});document.querySelector('#login-open').addEventListener('click',()=>{const p=document.querySelector('#login-preview');p.hidden=!p.hidden;});document.querySelectorAll('[data-provider]').forEach(b=>b.addEventListener('click',()=>{document.querySelector('#login-message').textContent=b.dataset.provider+' · '+t('loginDemo');}));document.querySelectorAll('.close-route').forEach(b=>b.addEventListener('click',()=>routeDialog.close()));
window.addEventListener('hashchange',()=>{if(drawer.open)drawer.close();if(routeDialog.open)routeDialog.close();closeLanguages();render();});window.addEventListener('pagehide',()=>{clearTimers();state.request=null;state.draft.name='';});
if(!location.hash||!['exchange','apply','loading','code','map','done'].includes(route()))history.replaceState(null,'','#/exchange');render();
